const green  = "#03A685";
const orange = "#FF6161";
const amber  = "#F5A623";
const ink    = "#282C3F";
const grey   = "#535766";
const greyLt = "#7E818C";
const border = "#EAEAEC";
const bg     = "#F0F0F0";

