  const [scr, setScr] = useState<S>("splash");
  const [prod, setProd] = useState<P>(PRODUCTS[0]);
  const [imgI, setImgI] = useState(0);
  const [size, setSize] = useState("");
  const [q, setQ] = useState("");
  const [ans, setAns] = useState("");
  const [busy, setBusy] = useState(false);
  const [bag, setBag] = useState(1);
  const ref = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scr === "splash") { const t = setTimeout(()=>setScr("wishlist"),2000); return ()=>clearTimeout(t); }
  }, [scr]);

  function open(p: P) { setProd(p); setImgI(0); setSize(""); setQ(""); setAns(""); setScr("product"); }

  async function ask() {
    if (!q.trim()||busy) return;
    setBusy(true);
    try {
      const r = await fetch("/api/verdict",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({productId:prod.id,question:q})});
      const d = await r.json();
      setAns(d.answer||"Not enough buyer data on this specific question.");
    } catch { setAns("Could not connect. Please try again."); }
    setBusy(false);
  }

  function addToBag() {
    if (!size) return;
    setBag(b=>b+1);
    setScr("success");
    setTimeout(()=>{ setSize(""); setScr("wishlist"); }, 2500);
  }

